}

function hazard(c, h, time, reduced) {
  const warning = h.phase === 'warning';
  const fade = h.phase === 'fade';
  const color = warning ? P.warning : P.danger;
  c.save(); c.globalAlpha = fade ? 0.25 : 1;
  c.fillStyle = warning ? 'rgba(255,191,105,0.09)' : 'rgba(255,42,58,0.16)';
  c.fillRect(h.x, h.y, h.w, h.h);
  c.save(); c.beginPath(); c.rect(h.x, h.y, h.w, h.h); c.clip();
  if (warning) {
    for (let x = h.x - h.h; x < h.x + h.w; x += 28) line(c, x, h.y + h.h, x + h.h, h.y, 'rgba(255,191,105,0.18)', 5);
    if (h.kind === 'slap') hand(c, h, true);
    else if (h.kind === 'glass') {
      // Double rectangular rim matches the glass hitbox, not a misleading circle.
      c.strokeStyle = P.warning; c.lineWidth = 3;
      c.strokeRect(h.x + 10, h.y + 10, Math.max(0, h.w - 20), Math.max(0, h.h - 20));
      c.strokeRect(h.x + 18, h.y + 18, Math.max(0, h.w - 36), Math.max(0, h.h - 36));
    } else {
      // A row of chevrons distinguishes a sweeping band even without colour.
      const cy = h.y + h.h / 2;
      for (let x = h.x + 26; x < h.x + h.w - 12; x += 54) {
        line(c, x - 12, cy - 16, x + 8, cy, P.warning, 4);
        line(c, x + 8, cy, x - 12, cy + 16, P.warning, 4);
      }
    }
  } else if (h.kind === 'slap') hand(c, h);
  else if (h.kind === 'glass') {
    c.fillStyle = P.glass; c.fillRect(h.x + 3, h.y + 3, h.w - 6, h.h - 6);
    c.strokeStyle = P.glassEdge; c.lineWidth = 5;
    c.strokeRect(h.x + 6, h.y + 6, Math.max(0, h.w - 12), Math.max(0, h.h - 12));
    ellipse(c, h.x + h.w / 2, h.y + h.h / 2, Math.max(1, h.w / 2 - 12), Math.max(1, h.h / 2 - 12), 'rgba(190,226,255,0.06)');
    line(c, h.x + 15, h.y + 20, h.x + 15, h.y + h.h - 20, '#c3e5ff', 3);
  } else {
    c.fillStyle = P.skinShade; c.fillRect(h.x, h.y + h.h * 0.24, h.w, h.h * 0.52);
    c.fillStyle = P.skin; c.fillRect(h.x, h.y + h.h * 0.24, h.w, h.h * 0.14);
    for (let x = h.x + 22; x < h.x + h.w; x += 48) {
      line(c, x + 12, h.y + h.h * 0.5, x, h.y + h.h * 0.4, P.nail, 2);
      line(c, x, h.y + h.h * 0.4, x + 12, h.y + h.h * 0.3, P.nail, 2);
    }
  }
  c.restore();
